let log = []
fn one(label, url, hdrs){
    log.push("--- " + label)
    let p = promise()
    net.http_request(net.HttpRequest{url: url method: net.HttpMethod.GET headers: hdrs}) do net.HttpEvents{
        on_response: |res| { log.push("  ok status " + res.status_code + " bytes " + res.body.to_string().len()) p.resolve(res) }
        on_error: |err| { log.push("  err: " + err.message) p.resolve(nil) }
    }
    let res = p.await()
    if res == nil { log.push("  nil") }
}
fn run(){
    log = []
    one("hn no-header", "https://hn.algolia.com/api/v1/search?tags=front_page&hitsPerPage=2", {})
    one("hn with UA", "https://hn.algolia.com/api/v1/search?tags=front_page&hitsPerPage=2", {"User-Agent": "Probe/1.0"})
    one("techmeme", "https://www.techmeme.com/feed.xml", {})
    one("googlenews", "https://news.google.com/rss?hl=en-US&gl=US&ceid=US:en", {})
    ui.out.render()
}
start_timeout(0.3, || run())

let ink = #x1c1c1e
SolidView{width: Fill height: Fill flow: Down padding: 12 spacing: 8 draw_bg.color: #xffffff
    Label{text: "net probe v6" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 20}}
    ButtonFlat{text: "run" on_click: || run()}
    out := ScrollYView{width: Fill height: Fill flow: Down spacing: 2 on_render: || {
        for line in log { Label{width: Fill text: line max_lines: 6 draw_text.color: ink draw_text.text_style.font_size: 12} }
    }}
}
